-- M1 第三块 PR2：会话文件（FR-15）。
-- Create "conversation_files" table
CREATE TABLE "conversation_files" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "org_id" bigint NOT NULL, "conversation_id" bigint NOT NULL, "user_id" bigint NOT NULL, "name" character varying NOT NULL, "kind" character varying NOT NULL, "size" bigint NOT NULL, "sha256" character varying NOT NULL, "object_key" character varying NOT NULL, "text" text NOT NULL DEFAULT '', "chars" bigint NOT NULL DEFAULT 0, "truncated" boolean NOT NULL DEFAULT false, "deleted_at" timestamptz NULL, PRIMARY KEY ("id"));
-- Create index "conversationfile_conversation_id_id" to table: "conversation_files"
CREATE INDEX "conversationfile_conversation_id_id" ON "conversation_files" ("conversation_id", "id");
